changeSet.sql:
ALTER TABLE task_type ADD COLUMN is_task BOOLEAN NOT NULL DEFAULT true;
ALTER TABLE task_type ADD COLUMN deleted BOOLEAN NOT NULL DEFAULT false;
ALTER TABLE task_type ADD COLUMN position INTEGER NOT NULL DEFAULT 0;

UPDATE task_type SET is_task = false WHERE name IN ('reminder', 'material');
UPDATE task_type SET color = 'yellow'
    WHERE name IN ('reminder', 'material') AND color = 'gray';

UPDATE task_type t SET position = s.rn FROM (
    SELECT name, row_number() OVER (ORDER BY is_task ASC, built_in DESC, name) AS rn
    FROM task_type
) s WHERE t.name = s.name;

ALTER TABLE note ALTER COLUMN task_type DROP DEFAULT;
ALTER TABLE note ALTER COLUMN task_type DROP NOT NULL;
UPDATE note SET task_type = NULL WHERE task_type = 'reminder';
